--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,58 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS_SPEC = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006-a: descuento global de 10 % sobre el total, IVA sobre lo descontado", () => {
+  assert.deepEqual(calcularFactura(LINEAS_SPEC, { descuentoGlobal: 10 }), {
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+    descuentoGlobalCentavos: 1105,
+  });
+});
+
+test("RF-006-b: sin descuento o con 0 % el resultado no cambia", () => {
+  const base = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS_SPEC), base);
+  assert.deepEqual(calcularFactura(LINEAS_SPEC, {}), base);
+  const cero = calcularFactura(LINEAS_SPEC, { descuentoGlobal: 0 });
+  assert.equal(cero.totalCentavos, 11050);
+  assert.equal(cero.ivaCentavos, 1437);
+  assert.equal(cero.netoCentavos, 9613);
+});
+
+test("RF-006-c: 100 % deja el total en 0", () => {
+  const f = calcularFactura(LINEAS_SPEC, { descuentoGlobal: 100 });
+  assert.equal(f.totalCentavos, 0);
+  assert.equal(f.ivaCentavos, 0);
+  assert.equal(f.netoCentavos, 0);
+});
+
+test("RF-006-d: descuento fuera de 0–100 o no numérico se rechaza", () => {
+  for (const malo of [-1, 100.01, NaN, Infinity, "10", null]) {
+    assert.throws(() => calcularFactura(LINEAS_SPEC, { descuentoGlobal: malo }), RangeError, String(malo));
+  }
+});
+
+test("RF-006-e: con porcentaje decimal los montos siguen enteros (ADR-001)", () => {
+  const f = calcularFactura(LINEAS_SPEC, { descuentoGlobal: 7.5 });
+  for (const v of Object.values(f)) assert.ok(Number.isInteger(v));
+  assert.equal(f.descuentoGlobalCentavos, 829);
+  assert.equal(f.totalCentavos, 10221);
+});
+
+test("RF-006-f: emitirFactura con descuento global devuelve factura congelada", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS_SPEC, descuentoGlobal: 10 });
+  assert.equal(f.totalCentavos, 9945);
+  assert.equal(f.descuentoGlobalCentavos, 1105);
+  assert.equal(f.estado, "emitida");
+  assert.ok(Object.isFrozen(f));
+});
